from pathlib import Path
from fractions import Fraction as F
from random import Random
import sys,json,hashlib,time
ROOT=Path.cwd();sys.path[:0]=[str(ROOT/'src'),str(ROOT/'tools')]
from eab.kernel2d.affine_motion import fit_affine,DDAAffineMotion
import m5a2_affine_replay as tool
rng=Random(5101502);start=time.perf_counter()

def solve(a,b):
    rows=[list(x)+[y] for x,y in zip(a,b)]
    for j in range(3):
        pivot=next(i for i in range(j,3) if rows[i][j]);rows[j],rows[pivot]=rows[pivot],rows[j]
        q=rows[j][j];rows[j]=[x/q for x in rows[j]]
        for i in range(3):
            if i!=j:
                q=rows[i][j];rows[i]=[x-q*y for x,y in zip(rows[i],rows[j])]
    return tuple(row[3] for row in rows)

def rotation(v,u):
    a,b=v[0]-u*v[1],v[1]+u*v[0]
    return ((a-u*b)/(1+u*u),(b+u*a)/(1+u*u))
for case in range(120):
    scale=(F(1,2**80),F(1),F(10**8))[case%3];shift=(0,1000,10**5,10**6)[case%4]
    points=tuple((scale*F(x,7)+shift,scale*F(y,11)-3*shift) for x,y in ((0,0),(4,0),(5,2),(3,4),(-1,3))[:3+case%3])
    matrix=tuple(tuple(F(rng.randrange(-20,21),17) for _ in range(2)) for _ in range(2))
    end=tuple(tuple(F(k+2)+sum(matrix[k][j]*p[j] for j in (0,1))+(F(1,10**100) if i==0 and k==0 and case%2 else 0) for k in (0,1)) for i,p in enumerate(points))
    rows=[(F(1),*p) for p in points];normal=[[sum(p[i]*p[j] for p in rows) for j in range(3)] for i in range(3)]
    coefficients=[solve(normal,[sum(p[i]*q[k] for p,q in zip(rows,end)) for i in range(3)]) for k in (0,1)]
    fitted=fit_affine(points,end)
    independent_ends=tuple(tuple(sum(p[i]*c[i] for i in range(3)) for c in coefficients) for p in rows)
    assert tuple(fitted.endpoint(p) for p in points)==independent_ends
    residual=tuple(tuple(q[k]-p[k] for k in (0,1)) for p,q in zip(independent_ends,end))
    assert residual==fitted.residuals and fitted.delta==max(abs(x) for p in residual for x in p)
    motion=DDAAffineMotion(fitted.matrix,F(rng.randrange(-20,21),23),fitted.translation,fitted.center)
    for p in points:
        v=tuple(p[k]-motion.center[k] for k in (0,1));r1=rotation(v,motion.u1)
        strain=tuple(sum(motion.matrix[k][j]*v[j] for j in (0,1))-r1[k] for k in (0,1))
        for s in (F(0),F(1,10**6),F(2,7),F(1)):
            rs=rotation(v,s*motion.u1)
            expected=tuple(motion.center[k]+s*motion.translation[k]+rs[k]+s*strain[k] for k in (0,1))
            assert motion.at(p,s)==expected
for case in range(100):
    boxes={b:(F(rng.randrange(-20,21),3),F(rng.randrange(-20,21),5),F(rng.randrange(1,9),4),F(rng.randrange(1,9),7)) for b in range(4)}
    polygons={b:((x,y),(x+w,y),(x+w,y+h),(x,y+h)) for b,(x,y,w,h) in boxes.items()}
    expected={}
    for b,(x,y,w,h) in boxes.items():
        expected[b]=min(max(F(0),xx-x-w,x-xx-ww)**2+max(F(0),yy-y-h,y-yy-hh)**2 for c,(xx,yy,ww,hh) in boxes.items() if b!=c)
    assert tool.nearest_gap_squares(polygons)==expected
summary={'complete':True,'fit_cases':120,'trajectory_cases':120,'rectangle_nearest_gap_cases':100,'mismatches':0,'seed':5101502,'independent_oracle':'raw-coordinate 3x3 Gaussian elimination; complex Cayley products; rectangle closed-form gaps','seconds':time.perf_counter()-start,'source_hashes':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in ('src/eab/kernel2d/affine_motion.py','tools/m5a2_affine_replay.py')}}
(ROOT/'reports/codex/M5a2_evidence/tmp/review_affine_numeric.json').write_text(json.dumps(summary,indent=2),encoding='utf-8');print(json.dumps(summary))

