        for row in map(json.loads,f):
            count+=1;steps[row['step']].append(row);zero+=F(row['delta_affine'])==0
            span=F(row['block_span']);eps=F(row['coordinate_epsilon_scale']);g=None if row['nearest_gap_square'] is None else F(row['nearest_gap_square'])
            for label,key in (('affine','delta_affine'),('rigid','delta_rigid')):
                d=F(row[key]);values[label+'_absolute'].append(d);values[label+'_over_block_span'].append(d/span);values[label+'_over_coordinate_epsilon'].append(d/eps)
