        assert data['distributions'][name]['quantiles_exact']==expected
        assert data['distributions'][name]['count']==len(v) and data['distributions'][name]['zero']==v.count(F(0))
        all_values[name].extend(v)
    sources={'snapshot':ROOT/'reports/codex/M5a_evidence/tmp/replay/inputs'/case/'shadow.jsonl','terminal':ROOT/'reports/codex/M5a_evidence/tmp/replay/inputs'/case/'geom.csv','m5a_normalized':ROOT/'reports/codex/M5a_evidence/tmp/replay/full_r1'/case/'normalized.jsonl.gz','m5a_audit':ROOT/'reports/codex/M5a_evidence/tmp/replay/full_r1'/case/'audit.json'}
    assert {k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in sources.items()}==data['input_hashes']
    case_checks[case]={'steps':len(steps),'quantile_families':len(values),'source_closure_files':len(sources),'matched':True}
for name,v in all_values.items():
